// Converte a resposta do modelo em itens para a planilha.
// Só passam itens com categoria, gênero e faixa etária dentro das listas permitidas;
// textos são limitados e têm caracteres iniciais de fórmula removidos (=, +, -, @).

const CATEGORIAS = ['Financeiro', 'Brinquedos', 'Roupas', 'Alimentos', 'Higiene'];
const GENEROS = ['Masculino', 'Feminino', 'Unissex', 'N/A'];
const FAIXAS = ['Bebê (0-2 anos)', 'Infantil (3-12 anos)', 'Juvenil (13-17 anos)', 'Adulto', 'Geral / N/A'];

const entrada = $input.first().json;
const resposta = String(entrada.output ?? entrada.text ?? '');
const conteudo = resposta.replace(/```(?:json)?/g, '').trim();

let itens;
try {
  itens = JSON.parse(conteudo);
} catch (erro) {
  throw new Error('A resposta do modelo não é um JSON válido.');
}
if (!Array.isArray(itens)) itens = [itens];

const texto = (valor, limite) =>
  String(valor ?? '').replace(/^[=+\-@\s]+/, '').slice(0, limite).trim();

const numero = (valor) => {
  const n = Number(valor);
  return Number.isFinite(n) && n >= 0 ? n : 0;
};

const validos = itens.filter((item) =>
  item &&
  CATEGORIAS.includes(item.categoria) &&
  GENEROS.includes(item.genero) &&
  FAIXAS.includes(item.faixa_etaria)
);

return validos.map((item) => ({
  json: {
    doador: texto(item.doador, 80) || 'Não informado',
    categoria: item.categoria,
    valor_reais: numero(item.valor_reais),
    qtd_itens: Math.floor(numero(item.qtd_itens)),
    genero: item.genero,
    faixa_etaria: item.faixa_etaria,
    descricao: texto(item.descricao, 300),
    status: 'Recebido',
  },
}));
